head.script:
scwin.onpageload = function() {
    var c_cnt = 5;
    var c_subName = "sub";
    var c_xmlName = ".xml";
    for (var i = 0; i < c_cnt; i++) {
        windowContainer1.createWindow(c_subName + i, null, 'windowContainer_listmenu_close_WESD-825_(WSQ-4805)_sub.xml', "",
            null, "existWindow", null, null);
    }
};
scwin.onpageunload = function() {};
scwin.getErrorLog = function() {
    var temp = WebSquare.logger.getErrorLog();
    return temp;
    // return temp.indexOf("error문구");
    // return temp.indexOf("error");
}
scwin.unitTest = function() {
    //Unit
    WebSquare.wUnit.start();
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('windowContainer1_windowList').click()");
    WebSquare.wUnit.addCommand("pause", "400");
    WebSquare.wUnit.addCommand("set", "document.getElementsByClassName('w2list_listColumn_close')[0].click()");
    WebSquare.wUnit.addCommand("pause", "400");
    WebSquare.wUnit.addCommand("assert", "scwin.getErrorLog() == ''", "true");
    WebSquare.wUnit.addCommand("pause", "500");
    //Run test and stop
    WebSquare.wUnit.run();
    WebSquare.wUnit.stop();
}
scwin.onpageload2 = function() {
    if (typeof scwin.onpageload === "function") {
        scwin.onpageload();
    }
    if (typeof scwin.unitTest === "function") {
        scwin.unitTest();
    }
}
